import type { Feature, MultiPolygon, Polygon } from 'geojson'

export interface CountryProperties {
  name: string
  /** ISO 3166-1 alpha-2 code, or null for territories without one. */
  code: string | null
}

export type CountryFeature = Feature<Polygon | MultiPolygon, CountryProperties>

// Shape of the static JSON files in public/data, generated by
// scripts/fetch-news.ts and scripts/fetch-food.ts.

// --- News ---

export interface Outlet {
  id: string
  name: string
  homepage: string
  /** BCP 47 language tag, e.g. "fr" or "pt-BR". */
  lang: string
}

export interface Headline {
  title: string
  link: string
  summary?: string
  image?: string
  /** ISO 8601 timestamp. */
  publishedAt?: string
}

export interface OutletFeed {
  outlet: Outlet
  /** ISO 8601 timestamp of the last successful fetch. */
  fetchedAt: string
  items: Headline[]
}

export interface CountryNews {
  country: string
  outlets: OutletFeed[]
}

/** data/index.json: which countries have news available. */
export interface NewsIndex {
  updatedAt: string
  countries: string[]
}

// --- Food ---

export interface Recipe {
  ingredients: string[]
  steps: string[]
  /** Page the recipe was taken from (Wikibooks Cookbook, CC BY-SA). */
  source: string
}

export interface Dish {
  id: string
  /** English name, e.g. "Pizza napoletana". */
  name: string
  /** Name in the country's language, when it differs, e.g. "Pizza napoletana" / "寿司". */
  localName?: string
  /** Short description from Wikipedia (CC BY-SA). */
  description?: string
  image?: string
  wikipedia?: string
  recipe?: Recipe
  /** Always present: a recipe video search, the fallback when there is no recipe. */
  videoSearch: string
}

export interface CountryFood {
  country: string
  dishes: Dish[]
}

/** data/food/index.json: which countries have dishes available. */
export interface FoodIndex {
  updatedAt: string
  countries: string[]
}
